/// Stored model fixture only. Default fields are intentional test data, never a
/// production observation fallback or proof that an actual artifact was checked.
fn task(id: &str, status: &str) -> Task {
    Task {
        id: id.into(),
        title: id.into(),
        status: status.into(),
        plan_max_attempts: 3,
        ..Default::default()
    }
}
